        try:
            result = db.query(
                "SELECT added_time::date as date, status, count(*)"
                " FROM import_item "
                " WHERE added_time > current_date - interval '$ndays' day"
                " GROUP BY 1, 2"
                " ORDER BY 1 desc",
                vars=locals(),
